"""Implementation of actions for the Login UI in the Mosaiq application"""
from .objects.mosaiq_core_objects import MosaiqCoreObjects
from interops.libraries.squish_actions import CommonActions
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME
from interops.libraries.squish_actions.exceptions import FailedToFindObject
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def wait_for_login_fields(waitTimeout: int = 30000) -> None:
    """Waits until both credential fields are ready in the MOSAIQ login form."""
    try:
        squishtest.waitForObject(MosaiqCoreObjects.dashboard_Username_TextBox, waitTimeout)
        squishtest.waitForObject(MosaiqCoreObjects.dashboard_Password_TextBox, waitTimeout)
    except LookupError as error:
        raise RuntimeError(
            "MOSAIQ login fields did not appear; verify the AUT is at the staff login screen"
        ) from error

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def enter_username(username: str) -> None:
    """Locates the Username text box on the main dashboard > types in the given Username string.

    :param str username: Username to be entered into the Username textbox
    """
    CommonActions.type_in_textfield(MosaiqCoreObjects.dashboard_Username_TextBox, username)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def enter_password(password: str) -> None:
    """Locates the Password text box on the main dashboard > types in the given Password string.

    :param str password: Password to be entered into the Password textbox
    """
    CommonActions.type_in_textfield(MosaiqCoreObjects.dashboard_Password_TextBox, password)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_login_button() -> None:
    """Locates the Login Button on the main dashboard > clicks located object using the primary mouse button.
    """
    CommonActions.left_click_object(MosaiqCoreObjects.dashboard_Login_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def confirm_sucessful_login(waitTimeout: int=10000) -> bool:
    """Waits for the main Mosaiq Tool bar to appear and Returns True if it successfully does.

    :return: True or False
    :rtype: bool
    """
    try:
        return True if CommonActions.find_object(MosaiqCoreObjects.tabBar_TabItem_Work_List, waitTimeout) is not None else False
    except FailedToFindObject:
        return False

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_quick_approval() -> None:
    """Clicks the Quick Approval checkbox on the main dashboard.
    :return: True or False
    :rtype: bool
    """
    CommonActions.left_click_object(MosaiqCoreObjects.dashboard_quick_approval_checkbox)
    
    